CREATE TABLE IF NOT EXISTS push_subscribers(id TEXT PRIMARY KEY,endpoint TEXT UNIQUE NOT NULL,subscription JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,name TEXT NOT NULL,user_id TEXT,properties JSONB NOT NULL DEFAULT '{}'::jsonb,timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS events_timestamp_idx ON events(timestamp DESC);
